/** Procedural, labelled test animations. Descriptions are generated by the real VLM, never supplied here. */
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { painter } from './create-fixtures.ts';
import { ffmpegPath } from '../apps/worker/src/video.ts';

const output = path.resolve('data/semantic-demo');
await mkdir(output, { recursive: true });
const base = 'http://127.0.0.1:4000/api';
const login = await fetch(`${base}/auth/login`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ email: 'manager@jaga.local', password: 'JagaLocal!2026' }) });
if (!login.ok) throw new Error('Sign-in failed. This demonstration uses the local seeded management account.');
const cookie = login.headers.get('set-cookie')!.split(';')[0];
const results: any[] = [];
for (const spec of [{ key: 'red-white', shirt: [203, 39, 46], car: [242, 244, 246] }, { key: 'blue-dark', shirt: [27, 87, 200], car: [35, 40, 47] }, { key: 'empty-white', shirt: null, car: [242, 244, 246] }]) {
  const file = path.join(output, `synthetic-${spec.key}.mp4`);
  const ffmpeg = spawn(ffmpegPath, ['-y', '-hide_banner', '-loglevel', 'error', '-f', 'rawvideo', '-pixel_format', 'rgb24', '-video_size', '640x360', '-framerate', '8', '-i', 'pipe:0', '-an', '-c:v', 'libx264', '-pix_fmt', 'yuv420p', '-movflags', '+faststart', file], { windowsHide: true, stdio: ['pipe', 'ignore', 'inherit'] });
  const completed = once(ffmpeg, 'exit');
  for (let i = 0; i < 64; i++) {
    const buffer = Buffer.alloc(640 * 360 * 3), p = painter(buffer);
    p.rect(0, 0, 640, 360, [156, 192, 208]); p.rect(0, 105, 640, 35, [92, 143, 89]); p.rect(0, 140, 640, 220, [135, 142, 148]);
    p.rect(0, 0, 640, 38, [164, 36, 54]); p.text('SYNTHETIC TEST ANIMATION', 12, 10, 3, [255, 255, 255]);
    for (const x of [50, 280, 550]) p.line(x, 166, x, 335, 2, [242, 240, 226]);
    const car = spec.car as [number, number, number];
    p.rect(315, 190, 170, 55, car); p.rect(345, 156, 104, 47, car);
    p.rect(352, 164, 36, 31, [70, 110, 133]); p.rect(396, 164, 45, 31, [70, 110, 133]);
    p.circle(347, 244, 18, [24, 28, 34]); p.circle(454, 244, 18, [24, 28, 34]); p.circle(347, 244, 9, [151, 158, 166]); p.circle(454, 244, 9, [151, 158, 166]);
    p.rect(473, 205, 12, 10, [237, 210, 100]); p.rect(315, 207, 8, 10, [184, 52, 58]);
    if (spec.shirt) {
      const x = 116 + 175 * Math.min(1, i / 55), y = 168, stride = Math.sin(i * 0.65) * 8;
      p.circle(x, y, 13, [217, 169, 127]); p.line(x - 2, y + 22, x - 2, y + 61, 12, spec.shirt as [number, number, number]);
      p.line(x - 12, y + 25, x - 24, y + 52 + stride, 5, spec.shirt as [number, number, number]); p.line(x + 10, y + 25, x + 26, y + 50 - stride, 5, spec.shirt as [number, number, number]);
      p.line(x - 5, y + 62, x - 15 + stride, y + 110, 6, [28, 37, 52]); p.line(x + 5, y + 62, x + 16 - stride, y + 110, 6, [28, 37, 52]);
    }
    if (!ffmpeg.stdin.write(buffer)) await once(ffmpeg.stdin, 'drain');
  }
  ffmpeg.stdin.end(); if ((await completed)[0] !== 0) throw new Error('Demo animation generation failed.');
  const local = new Date(Date.now() + 8 * 3600000), day = Date.UTC(local.getUTCFullYear(), local.getUTCMonth(), local.getUTCDate()) - 8 * 3600000 - 86400000;
  const form = new FormData(); form.set('cameraId', 'cam_parking_b'); form.set('recordedAt', new Date(day + (20 * 60 + results.length * 12) * 60000).toISOString());
  form.set('title', `Synthetic test animation · ${spec.key}`);
  form.set('file', new Blob([await readFile(file)], { type: 'video/mp4' }), path.basename(file));
  const uploaded = await fetch(`${base}/videos`, { method: 'POST', headers: { cookie }, body: form });
  const video = await uploaded.json(); if (!uploaded.ok) throw new Error(JSON.stringify(video));
  const queued = await fetch(`${base}/videos/${video.id}/analyze`, { method: 'POST', headers: { cookie, 'content-type': 'application/json' }, body: '{}' });
  if (!queued.ok) throw new Error(await queued.text());
  results.push({ key: spec.key, videoId: video.id, recordedAt: video.recordedAt, synthetic: true });
  console.log(`${spec.key}: uploaded and queued for real local VLM inference (${video.id}).`);
}
await writeFile(path.join(output, 'manifest.json'), JSON.stringify(results, null, 2));
